//! Procedural noise images generated by 1402f6450, shared by ocean shaders.
use crate::noise::PERMUTATION;

/// The two RGBA8 uploads have different interpretation: permutation is UNORM,
/// gradients are SNORM. Dimensions are 256x256 and 256x1 respectively.
pub struct NoiseTexturePixels {
    pub permutation: Vec<u8>,
    pub gradients: Vec<u8>,
}

pub fn generate_noise_textures() -> NoiseTexturePixels {
    let mut permutation = Vec::with_capacity(256 * 256 * 4);
    for y in 0..256 {
        for x in 0..256 {
            let a = usize::from(PERMUTATION[x]);
            let b = usize::from(PERMUTATION[(x + 1) & 255]);
            permutation.extend_from_slice(&[
                PERMUTATION[(a + y) & 255],
                PERMUTATION[(a + y + 1) & 255],
                PERMUTATION[(b + y) & 255],
                PERMUTATION[(b + y + 1) & 255],
            ]);
        }
    }
    // Signed unit gradients quantized to 8-bit SNORM, in the source's order.
    let directions: [[i8; 3]; 16] = [
        [127, 127, 0],
        [-128, 127, 0],
        [127, -128, 0],
        [-128, -128, 0],
        [127, 0, 127],
        [-128, 0, 127],
        [127, 0, -128],
        [-128, 0, -128],
        [0, 127, 127],
        [0, -128, 127],
        [0, 127, -128],
        [0, -128, -128],
        [127, 127, 0],
        [0, -128, 127],
        [-128, 127, 0],
        [0, -128, -128],
    ];
    let gradients = PERMUTATION
        .iter()
        .flat_map(|&hash| {
            let [x, y, z] = directions[usize::from(hash & 15)];
            [x as u8, y as u8, z as u8, 0]
        })
        .collect();
    NoiseTexturePixels {
        permutation,
        gradients,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn procedural_noise_uploads_match_installed_generator() {
        let pixels = generate_noise_textures();
        for (line, (data, dimensions, format)) in
            include_str!("../../tests/fixtures/noise_textures.txt")
                .lines()
                .zip([
                    (&pixels.permutation, [256, 256], 28),
                    (&pixels.gradients, [256, 1], 31),
                ])
        {
            let row = line.split_whitespace().collect::<Vec<_>>();
            assert_eq!(row.len(), 5);
            let packed = u32::from_str_radix(row[1], 16).unwrap();
            assert_eq!((packed >> 13) & 255, format);
            assert_eq!(u32::from_str_radix(row[2], 16).unwrap(), dimensions[0]);
            assert_eq!(u32::from_str_radix(row[3], 16).unwrap(), dimensions[1]);
            assert_eq!(
                data.len(),
                dimensions[0] as usize * dimensions[1] as usize * 4
            );
            let hash = data.iter().fold(0xcbf29ce484222325u64, |hash, &byte| {
                (hash ^ u64::from(byte)).wrapping_mul(0x100000001b3)
            });
            assert_eq!(hash, u64::from_str_radix(row[4], 16).unwrap(), "{}", row[0]);
        }
    }
}
